#include <stdexcept>

class InsufficientFunds : public std::runtime_error
{
public:
    explicit InsufficientFunds(long long shortBy) : std::runtime_error{ "insufficient funds" }, m_shortBy{ shortBy } {}
    long long shortBy() const { return m_shortBy; }

private:
    long long m_shortBy{};
};

class Wallet
{
public:
    explicit Wallet(long long cents) : m_cents{ cents } {}
    long long balance() const { return m_cents; }

    void spend(long long cents)
    {
        if (cents > m_cents)
        {
            throw InsufficientFunds{ cents - m_cents };
        }
        m_cents -= cents;
    }

private:
    long long m_cents{};
};

unitTests:
static_assert(std::is_base_of_v<std::runtime_error, InsufficientFunds>);

TEST("spending within the balance") { Wallet w{ 1000 }; w.spend(250); CHECK_EQ(w.balance(), 750); w.spend(750); CHECK_EQ(w.balance(), 0); }
TEST("overspending throws and changes nothing") { Wallet w{ 100 }; CHECK_THROWS_AS(w.spend(101), InsufficientFunds); CHECK_EQ(w.balance(), 100); }
TEST("the exception carries the shortfall") { Wallet w{ 100 }; try { w.spend(350); CHECK(false); } catch (const InsufficientFunds& e) { CHECK_EQ(e.shortBy(), 250); CHECK_EQ(std::string{ e.what() }, "insufficient funds"); } }
TEST("it can be caught as a standard exception") { Wallet w{ 0 }; bool caught{ false }; try { w.spend(1); } catch (const std::exception&) { caught = true; } CHECK(caught); }

